'use client'
import { useState, useEffect } from 'react';
import { verifyUser, getSubmissions, syncUserStats, verifyOwnership, verifySubmissionAuth } from '@/app/actions';
import type { CFUser } from '@/lib/codeforces';
import { motion } from 'framer-motion';
import { Search, Trophy, Flame, Target, Sparkles, ArrowRight, Zap, Brain, Network, BookOpen, Lock, Share2, Mic } from 'lucide-react';
import { cn } from '@/lib/utils';
import { ActivityFeed } from './ActivityFeed';
import { ProductTour } from '@/components/features/onboarding/ProductTour';
import { UserHeatmap } from '@/components/features/UserHeatmap';
import { RivalryWidget } from '@/components/features/RivalryWidget';
import { getProblemsByRating } from '@/app/actions';

export function DashboardClient() {
    const [handle, setHandle] = useState('');
    const [user, setUser] = useState<CFUser | null>(null);
    const [submissions, setSubmissions] = useState<any[]>([]);
    const [stats, setStats] = useState({ streak: 0, totalSolved: 0, rank: 'Intro' });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [recommendation, setRecommendation] = useState<any>(null);

    const processStats = (u: CFUser, subs: any[]) => {
        // 1. Calculate Solved
        const solvedSet = new Set();
        subs.forEach(s => {
            if (s.verdict === 'OK') solvedSet.add(`${s.problem.contestId}-${s.problem.index}`);
        });

        // 2. Calculate Streak
        // 2. Calculate Streak (Accepted Solutions Only)
        let streak = 0;
        const acSubs = subs.filter(s => s.verdict === 'OK');

        if (acSubs.length > 0) {
            const dates = new Set(
                acSubs.map(s => new Date(s.creationTimeSeconds * 1000).toISOString().split('T')[0])
            );

            const today = new Date().toISOString().split('T')[0];

            // Better iterator
            let current = new Date();
            let count = 0;
            while (true) {
                const dateStr = current.toISOString().split('T')[0];
                if (dates.has(dateStr)) {
                    count++;
                    current.setDate(current.getDate() - 1);
                } else {
                    // Allow missing today if checked early
                    // (Streak is preserved if you solved yesterday, even if not yet today)
                    if (count === 0 && dateStr === today) {
                        current.setDate(current.getDate() - 1);
                        continue;
                    }
                    break;
                }
            }
            streak = count;
        }

        // 3. Determine Tier
        let rank = "Newbie";
        const r = u.rating || 0;
        if (r >= 1200) rank = "Pupil";
        if (r >= 1400) rank = "Specialist";
        if (r >= 1600) rank = "Expert";
        if (r >= 1900) rank = "CM";
        if (r >= 2100) rank = "Master";
        if (r >= 2400) rank = "GM";

        setStats({ streak, totalSolved: solvedSet.size, rank });

        syncUserStats(u.handle, {
            currentStreak: streak,
            totalSolved: solvedSet.size,
            maxRating: u.maxRating || 0,
            lastActive: new Date()
        }).catch(err => console.error("Failed to sync stats", err));
    };

    const [verificationStep, setVerificationStep] = useState<'input' | 'verify'>('input');
    const [verifying, setVerifying] = useState(false);

    const handleLogin = async (e?: React.FormEvent) => {
        if (e) e.preventDefault();
        if (!handle.trim()) return;

        setLoading(true);
        setError('');

        const data = await verifyUser(handle);
        if (data) {
            // STEP 1: Found User, Now Verify
            if (verificationStep === 'input') {
                setVerificationStep('verify');
                setLoading(false);
                return;
            }
        } else {
            setError('User not found on Codeforces');
            setLoading(false);
        }
    };

    const confirmSubmission = async () => {
        setVerifying(true);
        setError('');

        const auth = await verifySubmissionAuth(handle);
        if (auth.success) {
            // SUCCESS!
            const data = await verifyUser(handle); // Re-fetch to be safe
            if (data) {
                setUser(data);
                localStorage.setItem('cp-handle', handle);
                window.dispatchEvent(new Event('nav-update')); // Update Navbar

                // Fetch data
                const subs = await getSubmissions(handle);
                setSubmissions(subs);
                processStats(data, subs);

                const currentRating = data.rating || 800;
                const targetRating = Math.max(800, Math.ceil((currentRating + 100) / 100) * 100);
                getProblemsByRating(targetRating).then(probs => {
                    if (probs.length > 0) setRecommendation(probs[0]);
                });
            }
        } else {
            setError('Verification failed. We could not find a recent Compilation Error on 4A from you. Please try again.');
        }
        setVerifying(false);
    }

    // Auto-login check (skip verification if already logged in previously)
    useEffect(() => {
        const saved = localStorage.getItem('cp-handle');
        if (saved) {
            setHandle(saved);
            setLoading(true);
            verifyUser(saved).then(async (u) => {
                if (u) {
                    setUser(u);
                    const subs = await getSubmissions(saved);
                    setSubmissions(subs);
                    processStats(u, subs);
                    // ... rest of logic
                    const currentRating = u.rating || 800;
                    const targetRating = Math.max(800, Math.ceil((currentRating + 100) / 100) * 100);

                    getProblemsByRating(targetRating).then(probs => {
                        if (probs.length > 0) setRecommendation(probs[0]);
                    });
                }
                setLoading(false);
            });
        }
    }, []);

    if (!user) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-8">
                <div className="text-center space-y-4">
                    <h1 className="text-5xl font-extrabold bg-gradient-to-r from-blue-500 to-cyan-400 bg-clip-text text-transparent">
                        CP-ZeroToHero
                    </h1>
                    <p className="text-zinc-400 text-lg">Your guided path from Newbie to Master.</p>
                </div>

                <div className="w-full max-w-md bg-zinc-900/50 p-8 rounded-2xl border border-zinc-800 backdrop-blur-xl shadow-2xl">
                    <form onSubmit={handleLogin} className="flex flex-col gap-4">
                        {verificationStep === 'input' ? (
                            <div className="relative">
                                <Search className="absolute left-3 top-3.5 text-zinc-500 pointer-events-none" size={20} />
                                <input
                                    value={handle}
                                    onChange={(e) => setHandle(e.target.value)}
                                    placeholder="Enter Codeforces Handle"
                                    className="w-full bg-zinc-950 border border-zinc-800 rounded-lg py-3 pl-10 pr-4 focus:ring-2 focus:ring-blue-600 focus:outline-none transition text-white placeholder:text-zinc-600"
                                />
                                <button
                                    type="submit"
                                    disabled={loading}
                                    className="w-full mt-4 bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-lg font-bold transition disabled:opacity-50 flex justify-center items-center"
                                >
                                    {loading ? (
                                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    ) : 'Verify & Connect'}
                                </button>
                            </div>
                        ) : (
                            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
                                <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-lg text-sm text-red-200">
                                    <p className="font-bold flex items-center gap-2 mb-2">
                                        <Lock size={16} /> Anti-Impersonation Check
                                    </p>
                                    <p className="mb-2">To prove <b>{handle}</b> is yours:</p>
                                    <ol className="list-decimal list-inside space-y-2 text-zinc-300">
                                        <li>Go to <a href="https://codeforces.com/problemset/problem/4/A" target="_blank" className="text-blue-400 underline font-bold">Problem 4A (Watermelon)</a>.</li>
                                        <li>Submit a solution that causes a <b className="text-red-400">COMPILATION ERROR</b>.</li>
                                        <li className="text-xs text-zinc-500">(e.g. submit a file with just the text "verify me")</li>
                                        <li>Wait 10 seconds, then click below.</li>
                                    </ol>
                                </div>
                                <button
                                    type="button"
                                    onClick={confirmSubmission}
                                    disabled={verifying}
                                    className="w-full bg-green-600 hover:bg-green-700 text-white py-3 rounded-lg font-bold transition disabled:opacity-50 flex justify-center items-center"
                                >
                                    {verifying ? (
                                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    ) : 'I have submitted code'}
                                </button>
                                <button
                                    type="button"
                                    onClick={() => { setVerificationStep('input'); setError(''); }}
                                    className="w-full text-xs text-zinc-500 hover:text-white transition"
                                >
                                    Cancel / Change Handle
                                </button>
                            </div>
                        )}
                    </form>

                    {error && <p className="text-red-400 text-sm mt-4 text-center">{error}</p>}
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            {/* Header */}
            <div className="flex flex-col md:flex-row items-center md:items-start gap-6 bg-zinc-900/50 p-6 rounded-2xl border border-zinc-800 backdrop-blur-sm">
                <img src={user.titlePhoto} alt="Avatar" className="w-24 h-24 rounded-full border-4 border-zinc-800 shadow-xl" />
                <div className="text-center md:text-left">
                    <h2 className="text-3xl font-bold text-white flex items-center justify-center md:justify-start gap-3">
                        {user.handle}
                        <span className={cn("text-sm px-2 py-0.5 rounded-full border font-mono", getRatingColor(user.rating))}>
                            {user.rating || 0}
                        </span>
                    </h2>
                    <p className="text-zinc-400 mt-1 capitalize">{user.rank || 'Unrated'} • Peak: {user.maxRank} ({user.maxRating})</p>
                </div>
                <button
                    onClick={() => { localStorage.removeItem('cp-handle'); setUser(null); setHandle(''); }}
                    className="md:ml-auto px-4 py-2 text-sm text-zinc-500 hover:text-red-400 hover:bg-zinc-800 rounded-lg transition"
                >
                    Logout
                </button>
            </div>

            {/* Dashboard Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                {/* LEFT COL: Feature Arcade (Span 8) */}
                <div className="lg:col-span-8 space-y-6">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="h-1 w-1 rounded-full bg-blue-500"></div>
                        <h3 className="text-zinc-400 font-medium text-sm uppercase tracking-wider">The Arcade</h3>
                    </div>

                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                        {/* Hero Features (Span 2 cols sometimes) */}
                        <DashboardLink
                            href="/skills"
                            title="Skill Tree"
                            desc="RPG Progression"
                            icon={<Network size={20} />}
                            color="text-emerald-400"
                            bg="bg-emerald-500/10 border-emerald-500/20"
                        />
                        <DashboardLink
                            href="/flashback"
                            title="Flashback"
                            desc="SRS Memory"
                            icon={<Brain size={20} />}
                            color="text-pink-400"
                            bg="bg-pink-500/10 border-pink-500/20"
                        />

                        {/* Standard Features */}
                        <DashboardLink
                            href="/senpai"
                            title="AI Dojo"
                            desc="Get Hints"
                            icon={<Sparkles size={18} />}
                            color="text-indigo-400"
                            bg="bg-indigo-500/10 border-indigo-500/20"
                        />
                        <DashboardLink
                            href="/stress"
                            title="Stress Test"
                            desc="Find Bugs"
                            icon={<Zap size={18} />}
                            color="text-yellow-400"
                            bg="bg-yellow-500/10 border-yellow-500/20"
                        />
                        <DashboardLink
                            href="/racer"
                            title="Racer"
                            desc="Speed Code"
                            icon={<Flame size={18} />}
                            color="text-red-400"
                            bg="bg-red-500/10 border-red-500/20"
                        />
                        <DashboardLink
                            href="/studio"
                            title="Algo Studio"
                            desc="Visualizer"
                            icon={<Share2 size={18} />}
                            color="text-cyan-400"
                            bg="bg-cyan-500/10 border-cyan-500/20"
                        />
                        <DashboardLink
                            href="/interview"
                            title="Interviewer"
                            desc="Mock AI Test"
                            icon={<Mic size={18} />}
                            color="text-rose-400"
                            bg="bg-rose-500/10 border-rose-500/20"
                        />

                        {/* Resource Features */}
                        <DashboardLink
                            href="/roadmap"
                            title="Roadmap"
                            desc="Guide"
                            icon={<Target size={18} />}
                            color="text-blue-400"
                            bg="bg-blue-500/10 border-blue-500/20"
                        />
                        <DashboardLink
                            href="/contests"
                            title="Contests"
                            desc="Virtual"
                            icon={<Trophy size={18} />}
                            color="text-orange-400"
                            bg="bg-orange-500/10 border-orange-500/20"
                        />
                        <DashboardLink
                            href="/blog-hunter"
                            title="Blogs"
                            desc="Learn"
                            icon={<BookOpen size={18} />}
                            color="text-purple-400"
                            bg="bg-purple-500/10 border-purple-500/20"
                        />
                    </div>

                    {/* Activity Log (Moved here for width) */}
                    <div className="bg-zinc-900/40 p-6 rounded-2xl border border-zinc-800/50 mt-6">
                        <h3 className="text-zinc-500 text-xs font-bold uppercase mb-4 flex items-center gap-2">
                            <Flame className="text-zinc-600" size={14} /> Activity Heatmap
                        </h3>
                        <div className="h-32">
                            {submissions.length > 0 ? (
                                <UserHeatmap submissions={submissions} />
                            ) : (
                                <div className="h-full flex items-center justify-center text-zinc-600 text-sm">
                                    No recent activity found.
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* RIGHT COL: Mission Control (Span 4) */}
                <div className="lg:col-span-4 space-y-6">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="h-1 w-1 rounded-full bg-violet-500"></div>
                        <h3 className="text-zinc-400 font-medium text-sm uppercase tracking-wider">Mission Control</h3>
                    </div>

                    {/* Next Mission Card */}
                    <div className="bg-gradient-to-b from-violet-900/20 to-zinc-900 border border-violet-500/30 p-6 rounded-2xl relative overflow-hidden group hover:border-violet-500/50 transition duration-500">
                        <div className="relative z-10">
                            <div className="flex justify-between items-start mb-4">
                                <div className="p-3 bg-violet-500/20 rounded-xl text-violet-300">
                                    <Target size={24} />
                                </div>
                                <span className="bg-violet-500/20 text-violet-300 text-[10px] uppercase font-bold px-2 py-1 rounded">
                                    Recommended
                                </span>
                            </div>

                            {recommendation ? (
                                <>
                                    <div className="text-zinc-400 text-xs uppercase font-bold tracking-wider mb-1">Daily Challenge</div>
                                    <div className="font-mono text-2xl text-white font-bold mb-2 leading-tight">{recommendation.name}</div>
                                    <div className="flex gap-2 text-xs text-violet-300/60 mb-6">
                                        {recommendation.tags.slice(0, 3).join(', ')} • {recommendation.rating}
                                    </div>
                                    <a
                                        href={`https://codeforces.com/problemset/problem/${recommendation.contestId}/${recommendation.index}`}
                                        target="_blank"
                                        className="w-full flex items-center justify-center gap-2 text-sm bg-violet-600 hover:bg-violet-500 text-white px-4 py-3 rounded-xl font-bold transition shadow-lg shadow-violet-900/20"
                                    >
                                        Solve Now <ArrowRight size={16} />
                                    </a>
                                </>
                            ) : (
                                <p className="text-zinc-500 py-4">Scanning your stats for correct difficulty...</p>
                            )}
                        </div>
                        {/* Background Decoration */}
                        <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-violet-600/10 blur-[50px] rounded-full pointer-events-none" />
                    </div>

                    {/* Stats Summary (Vertical) */}
                    <div className="bg-zinc-900/40 border border-zinc-800 rounded-2xl p-4 space-y-4">
                        <div className="flex items-center justify-between p-2">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-yellow-500/10 rounded-lg text-yellow-400"><Trophy size={16} /></div>
                                <span className="text-zinc-400 text-sm">Tier</span>
                            </div>
                            <span className="font-bold text-white">{stats.rank}</span>
                        </div>
                        <div className="flex items-center justify-between p-2 border-t border-zinc-800/50">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-orange-500/10 rounded-lg text-orange-400"><Flame size={16} /></div>
                                <span className="text-zinc-400 text-sm">Streak</span>
                            </div>
                            <span className="font-bold text-white">{stats.streak} Days</span>
                        </div>
                        <div className="flex items-center justify-between p-2 border-t border-zinc-800/50">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-green-500/10 rounded-lg text-green-400"><Target size={16} /></div>
                                <span className="text-zinc-400 text-sm">Solved</span>
                            </div>
                            <span className="font-bold text-white">{stats.totalSolved}</span>
                        </div>
                    </div>

                    {/* Rivals */}
                    <div className="bg-zinc-900/40 rounded-2xl border border-zinc-800/50 overflow-hidden">
                        <div className="p-4 border-b border-zinc-800/50 flex justify-between items-center">
                            <h3 className="text-xs font-bold text-zinc-500 uppercase">Rival Watch</h3>
                            <a href="#" className="text-xs text-zinc-600 hover:text-zinc-400">Manage</a>
                        </div>
                        <div className="p-2">
                            <RivalryWidget user={user} compact={true} />
                        </div>
                    </div>

                </div>
            </div>
            {/* Product Tour Overlay */}
            <ProductTour />
        </div>
    );
}

function DashboardLink({ href, title, desc, icon, color, bg, className }: any) {
    return (
        <a
            href={href}
            className={cn(
                "group relative p-4 rounded-2xl border transition-all duration-300 hover:-translate-y-1 hover:shadow-xl overflow-hidden",
                bg, // Dynamic background/border
                className
            )}
        >
            <div className="relative z-10">
                <div className={cn("p-2 rounded-lg w-fit mb-3 transition-colors", color.replace('text-', 'bg-') + '/10', color)}>
                    {icon}
                </div>
                <h4 className={cn("font-bold text-lg mb-0.5 text-zinc-200 group-hover:text-white transition")}>{title}</h4>
                <p className="text-xs text-zinc-500 group-hover:text-zinc-400">{desc}</p>
            </div>

            <div className={cn(
                "absolute -right-4 -bottom-4 opacity-0 group-hover:opacity-10 transition-opacity duration-500",
                color
            )}>
                {/* Giant Icon Background */}
                {/* Clone the icon but make it huge? Easy way is just SVGs usually scaling */}
            </div>
        </a>
    )
}

function getRatingColor(rating?: number) {
    if (!rating) return "text-white border-zinc-600";
    if (rating < 1200) return "text-gray-300 border-gray-600 bg-gray-500/10";
    if (rating < 1400) return "text-green-400 border-green-700 bg-green-500/10";
    if (rating < 1600) return "text-cyan-400 border-cyan-700 bg-cyan-500/10";
    if (rating < 1900) return "text-blue-500 border-blue-800 bg-blue-500/10";
    if (rating < 2100) return "text-purple-400 border-purple-700 bg-purple-500/10";
    if (rating < 2400) return "text-orange-400 border-orange-700 bg-orange-500/10";
    return "text-red-500 border-red-700 bg-red-500/10";
}
